/* Rush Duel online transport bridge.
   Keeps the small PeerJS-style API used by index.html, but carries messages
   through secure MQTT WebSockets so mobile NAT/firewalls cannot block rooms. */
(()=>{
  'use strict';

  const MQTT_SOURCES=[
    'https://cdn.jsdelivr.net/npm/mqtt@5.15.2/dist/mqtt.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/mqtt/5.14.1/mqtt.min.js',
    'https://unpkg.com/mqtt@5.15.2/dist/mqtt.min.js'
  ];
  const BROKERS=[
    'wss://broker.emqx.io:8084/mqtt',
    'wss://broker.hivemq.com:8884/mqtt'
  ];
  const APP_TOPIC='rush-duel-live-v4';
  let mqttLoadPromise=null;

  class Emitter{
    constructor(){this._events=new Map();}
    on(name,fn){if(typeof fn!=='function')return this;const list=this._events.get(name)||[];list.push(fn);this._events.set(name,list);return this;}
    once(name,fn){const wrapped=(...args)=>{this.off(name,wrapped);fn(...args);};return this.on(name,wrapped);}
    off(name,fn){const list=this._events.get(name);if(!list)return this;this._events.set(name,list.filter(item=>item!==fn));return this;}
    removeListener(name,fn){return this.off(name,fn);}
    removeAllListeners(name){if(name)this._events.delete(name);else this._events.clear();return this;}
    emit(name,...args){const list=(this._events.get(name)||[]).slice();for(const fn of list){try{fn(...args);}catch(error){setTimeout(()=>{throw error;},0);}}return list.length>0;}
  }

  const randomId=(prefix='p')=>`${prefix}-${crypto.getRandomValues(new Uint32Array(3)).join('-')}`;
  const safeId=value=>String(value||'').toLowerCase().replace(/[^a-z0-9_-]/g,'').slice(0,80);
  const inbox=id=>`${APP_TOPIC}/${safeId(id)}/inbox`;
  const makeError=(type,message)=>Object.assign(new Error(message),{type});

  function loadScript(src){
    return new Promise((resolve,reject)=>{
      const script=document.createElement('script');
      script.src=src;script.async=true;script.crossOrigin='anonymous';
      script.onload=()=>window.mqtt?resolve(window.mqtt):reject(new Error('MQTT library did not initialize.'));
      script.onerror=()=>reject(new Error(`Could not load ${src}`));
      document.head.appendChild(script);
    });
  }

  function loadMqtt(){
    if(window.mqtt?.connect)return Promise.resolve(window.mqtt);
    if(mqttLoadPromise)return mqttLoadPromise;
    mqttLoadPromise=(async()=>{
      let lastError;
      for(const src of MQTT_SOURCES){
        try{return await loadScript(src);}catch(error){lastError=error;}
      }
      throw lastError||new Error('Online transport could not load.');
    })();
    return mqttLoadPromise;
  }

  class DataConnection extends Emitter{
    constructor(provider,peerId,options={}){
      super();
      this.provider=provider;
      this.peer=peerId;
      this.metadata=options.metadata||null;
      this.serialization=options.serialization||'json';
      this.reliable=true;
      this.open=false;
      this.connectionId=options.session||randomId('session');
      this._closed=false;
      this._joinTimer=0;
      this._joinStarted=0;
    }
    _markOpen(){
      if(this._closed||this.open)return;
      clearInterval(this._joinTimer);this._joinTimer=0;
      this.open=true;
      queueMicrotask(()=>{if(!this._closed)this.emit('open');});
    }
    _receive(payload){if(!this._closed)this.emit('data',payload);}
    send(payload){
      if(!this.open||this._closed)throw makeError('not-open-yet','Connection is not open.');
      this.provider._sendEnvelope({type:'data',to:this.peer,session:this.connectionId,payload});
    }
    close(options={}){
      if(this._closed)return;
      this._closed=true;this.open=false;
      clearInterval(this._joinTimer);this._joinTimer=0;
      this.provider._connections.delete(this.connectionId);
      if(!options.silent)this.provider._sendEnvelope({type:'close',to:this.peer,session:this.connectionId});
      queueMicrotask(()=>this.emit('close'));
    }
  }

  class Peer extends Emitter{
    constructor(id,options={}){
      super();
      this.id=safeId(id)||randomId('rush-guest');
      this.options=options;
      this.open=false;
      this.disconnected=false;
      this.destroyed=false;
      this._client=null;
      this._brokerIndex=0;
      this._attemptToken=0;
      this._connections=new Map();
      this._outbox=[];
      this._everOpened=false;
      this._manualStop=false;
      setTimeout(()=>this._start(),0);
    }

    async _start(){
      try{await loadMqtt();if(!this.destroyed)this._connectBroker(this._brokerIndex);}
      catch(error){if(!this.destroyed)this.emit('error',makeError('network',error?.message||'Online transport failed to load.'));}
    }

    _connectBroker(index){
      if(this.destroyed)return;
      const mqttApi=window.mqtt;
      if(!mqttApi?.connect){this._start();return;}
      const token=++this._attemptToken;
      this._brokerIndex=((index%BROKERS.length)+BROKERS.length)%BROKERS.length;
      const broker=BROKERS[this._brokerIndex];
      const client=mqttApi.connect(broker,{
        clientId:`rd_${randomId('client').replace(/-/g,'').slice(0,38)}`,
        clean:true,
        keepalive:20,
        connectTimeout:8000,
        reconnectPeriod:0,
        protocolVersion:4,
        resubscribe:false,
        forceNativeWebSocket:true
      });
      this._client=client;
      let connected=false;
      let failed=false;
      const failover=(reason)=>{
        if(failed||this.destroyed||token!==this._attemptToken)return;
        failed=true;
        try{client.end(true);}catch{}
        if(!this._everOpened){
          this._brokerIndex=(this._brokerIndex+1)%BROKERS.length;
          setTimeout(()=>{if(!this.destroyed&&token===this._attemptToken)this._connectBroker(this._brokerIndex);},300);
        }else{
          this.open=false;this.disconnected=true;
          this.emit('disconnected',this.id);
          if(reason)this.emit('error',makeError('network',reason));
        }
      };

      client.on('connect',()=>{
        if(this.destroyed||token!==this._attemptToken)return;
        connected=true;
        client.subscribe(inbox(this.id),{qos:0},error=>{
          if(error){failover('Could not create the online room channel.');return;}
          if(this.destroyed||token!==this._attemptToken)return;
          this.open=true;this.disconnected=false;this._everOpened=true;
          this.emit('open',this.id);
          const queued=this._outbox.splice(0);
          for(const envelope of queued)this._sendEnvelope(envelope);
        });
      });
      client.on('message',(_topic,buffer)=>{
        if(this.destroyed||token!==this._attemptToken)return;
        try{
          const message=JSON.parse(buffer.toString());
          if(message?.v!==4||message.to!==this.id||message.from===this.id)return;
          this._handleEnvelope(message);
        }catch{}
      });
      client.on('error',error=>{
        if(!connected)failover(error?.message||'The online room service could not be reached.');
      });
      client.on('close',()=>{
        if(this.destroyed||this._manualStop||token!==this._attemptToken||failed)return;
        failover(connected?'The online room service disconnected.':'The online room service did not answer.');
      });
      setTimeout(()=>{if(!connected&&!failed&&token===this._attemptToken)failover('The online room service timed out.');},9000);
    }

    _sendEnvelope(envelope){
      const message={v:4,from:this.id,at:Date.now(),...envelope};
      if(!message.to)return false;
      if(!this.open||!this._client?.connected){this._outbox.push(envelope);return false;}
      try{
        this._client.publish(inbox(message.to),JSON.stringify(message),{qos:0,retain:false});
        return true;
      }catch{return false;}
    }

    _handleEnvelope(message){
      if(message.type==='join'){
        let connection=this._connections.get(message.session);
        if(!connection){
          connection=new DataConnection(this,message.from,{session:message.session,metadata:message.metadata,serialization:message.serialization});
          this._connections.set(message.session,connection);
          this.emit('connection',connection);
          connection._markOpen();
        }
        this._sendEnvelope({type:'accept',to:message.from,session:message.session});
        return;
      }
      const connection=this._connections.get(message.session);
      if(!connection)return;
      if(message.type==='accept'){connection._markOpen();return;}
      if(message.type==='data'){connection._receive(message.payload);return;}
      if(message.type==='close')connection.close({silent:true});
    }

    connect(peerId,options={}){
      const target=safeId(peerId);
      const connection=new DataConnection(this,target,{...options,session:randomId('session')});
      this._connections.set(connection.connectionId,connection);
      const sendJoin=()=>{
        if(connection._closed||connection.open)return;
        this._sendEnvelope({type:'join',to:target,session:connection.connectionId,metadata:connection.metadata,serialization:connection.serialization});
      };
      connection._joinStarted=Date.now();
      sendJoin();
      connection._joinTimer=setInterval(()=>{
        if(connection._closed||connection.open){clearInterval(connection._joinTimer);return;}
        if(Date.now()-connection._joinStarted>6500){
          clearInterval(connection._joinTimer);connection._joinTimer=0;
          this.emit('error',makeError('peer-unavailable',`Room ${target} is not available.`));
          connection.close({silent:true});
          return;
        }
        sendJoin();
      },850);
      return connection;
    }

    reconnect(){
      if(this.destroyed)throw new Error('This peer has been destroyed.');
      if(!this.disconnected&&!this._client)return this._start();
      this._manualStop=true;
      try{this._client?.end(true);}catch{}
      this._manualStop=false;
      this.open=false;this.disconnected=false;
      this._connectBroker(this._brokerIndex+1);
    }

    disconnect(){
      if(this.destroyed||this.disconnected)return;
      this._manualStop=true;this.open=false;this.disconnected=true;
      try{this._client?.end(true);}catch{}
      this._manualStop=false;
      this.emit('disconnected',this.id);
    }

    destroy(){
      if(this.destroyed)return;
      this.destroyed=true;this.open=false;this.disconnected=true;this._manualStop=true;
      for(const connection of [...this._connections.values()])connection.close();
      this._connections.clear();this._outbox.length=0;
      try{this._client?.end(true);}catch{}
      this._client=null;
      queueMicrotask(()=>this.emit('close'));
    }
  }

  window.peerjs={Peer,transport:'mqtt-websocket-relay-v4'};
  window.Peer=Peer;
})();
